// "Most relevant" ▾: the menu of comment orders, positioned under its
// trigger.
import { useCallback, useRef, useState } from "react";
import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import UIText from "UIText.react";
import UIIcon from "UIIcon.react";
import UIPressable from "UIPressable.react";
import UIPopover from "UIPopover.react";
import UIMenu, { UIMenuItem } from "UIMenu.react";
import { UIRow } from "UIStack.react";

const styles = stylex.create({
  trigger: { gap: 4, paddingBlock: 8, alignSelf: "flex-start" },
});

export default function CommentOrderSelector({ feedback, onChange }) {
  const data = useFragment(
    graphql`
      fragment CommentOrderSelector_feedback on Feedback {
        selected_order
        ordering_options {
          key
          title
          description
        }
      }
    `,
    feedback,
  );
  const anchor = useRef(null);
  const [open, setOpen] = useState(false);
  const [selected, setSelected] = useState(data.selected_order);
  const close = useCallback(() => setOpen(false), []);
  const current = data.ordering_options.find((option) => option.key === selected) ?? data.ordering_options[0];
  return (
    <span ref={anchor}>
      <UIPressable label={current?.title} onPress={() => setOpen((value) => !value)} showOverlay={false} testid="comment-order-trigger" aria-expanded={open}>
        <UIRow xstyle={styles.trigger}>
          <UIText type="meta" weight="semibold">
            {current?.title}
          </UIText>
          <UIIcon name="caretDown" size={14} />
        </UIRow>
      </UIPressable>
      {open ? (
        <UIPopover anchorRef={anchor} onClose={close} label="Comment order" align="start" width={340} testid="comment-order-menu">
          <UIMenu label="Comment order">
            {data.ordering_options.map((option) => (
              <UIMenuItem
                key={option.key}
                label={option.title}
                description={option.description}
                selected={option.key === selected}
                testid={`comment-order-${option.key}`}
                onPress={() => {
                  setSelected(option.key);
                  setOpen(false);
                  onChange(option.key);
                }}
              />
            ))}
          </UIMenu>
        </UIPopover>
      ) : null}
    </span>
  );
}
