// A modal dialog over the page: an overlay, a focus trap, Escape to close,
// and the page's scroll locked underneath.
import { useEffect } from "react";
import * as stylex from "@stylexjs/stylex";
import { colors, radii } from "BaseTokens.stylex";
import { elevation } from "ElevationTokens.stylex";
import UILayer from "UILayer.react";
import UIFocusScope from "UIFocusScope.react";

const styles = stylex.create({
  overlay: { position: "fixed", inset: 0, zIndex: 50, display: "flex", alignItems: "flex-start", justifyContent: "center", backgroundColor: colors.overlayAlpha80, overflowY: "auto", paddingBlock: 32 },
  dialog: { position: "relative", backgroundColor: colors.surfaceBackground, borderRadius: radii.lg, boxShadow: elevation.e5, display: "flex", flexDirection: "column", maxHeight: "calc(100vh - 64px)" },
  width: (width) => ({ width }),
});

export default function UIDialog({ label, onClose, width = 700, children, testid }) {
  useEffect(() => {
    const onKeyDown = (event) => {
      if (event.key === "Escape") {
        onClose?.();
      }
    };
    document.addEventListener("keydown", onKeyDown);
    const previousOverflow = document.documentElement.style.overflow;
    document.documentElement.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", onKeyDown);
      document.documentElement.style.overflow = previousOverflow;
    };
  }, [onClose]);
  return (
    <UILayer>
      <div {...stylex.props(styles.overlay)} data-vc-root="dialog">
        <UIFocusScope trap>
          <div role="dialog" aria-modal="true" aria-label={label} data-testid={testid} {...stylex.props(styles.dialog, styles.width(width))}>
            {children}
          </div>
        </UIFocusScope>
      </div>
    </UILayer>
  );
}
