// The dialog's comments: the order selector, the list, and the next page,
// loaded when the list's end scrolls into view.
import { useCallback, useEffect, useRef, useTransition } from "react";
import { graphql, usePaginationFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { commentTokens } from "ComponentTokens.stylex";
import fbt from "fbt";
import UIText from "UIText.react";
import UIPressable from "UIPressable.react";
import UISpinner from "UISpinner.react";
import { UIColumn, UIRow } from "UIStack.react";
import LoggingSurface from "LoggingSurface.react";
import Comment from "Comment.react";
import CommentOrderSelector from "CommentOrderSelector.react";
import { emitStepEvent } from "Workload";
import PerfLogger from "PerfLogger";

const PAGE = 10;

const styles = stylex.create({
  list: { paddingInline: 16, paddingBottom: 12, gap: commentTokens.gap },
  more: { paddingBlock: 8 },
  sentinel: { height: 1 },
  loading: { justifyContent: "center", paddingBlock: 8 },
});

export default function PostDialogComments({ feedback }) {
  const { data, loadNext, hasNext, isLoadingNext, refetch } = usePaginationFragment(
    graphql`
      fragment PostDialogComments_feedback on Feedback
      @refetchable(queryName: "PostDialogCommentsPaginationQuery")
      @argumentDefinitions(count: { type: "Int", defaultValue: 10 }, cursor: { type: "String" }, orderby: { type: "String", defaultValue: "RANKED_RELEVANT" }) {
        id
        selected_order
        comment_count {
          total_count
        }
        ...CommentOrderSelector_feedback
        display_comments(first: $count, after: $cursor, orderby: $orderby) @connection(key: "PostDialogComments_display_comments", filters: ["orderby"]) {
          edges {
            node {
              id
              ...Comment_comment
            }
          }
        }
      }
    `,
    feedback,
  );
  const [isRefetching, startRefetch] = useTransition();
  const edges = data?.display_comments?.edges ?? [];
  const sentinel = useRef(null);
  const state = useRef(null);
  state.current = { hasNext, isLoadingNext, loadNext };

  const changeOrder = useCallback(
    (orderby) => {
      const instance = PerfLogger.newInstanceKey();
      PerfLogger.markerStart("comment_order", instance);
      startRefetch(() => {
        refetch(
          { orderby, count: PAGE, cursor: null },
          {
            fetchPolicy: "network-only",
            onComplete: () => {
              PerfLogger.markerEnd("comment_order", "success", instance);
              emitStepEvent("comments-reordered", { orderby });
            },
          },
        );
      });
    },
    [refetch],
  );

  const loadMore = useCallback(() => {
    const { hasNext: more, isLoadingNext: loading, loadNext: next } = state.current;
    if (!more || loading) {
      return;
    }
    next(PAGE, { onComplete: () => emitStepEvent("comments-page-loaded") });
  }, []);

  useEffect(() => {
    const root = sentinel.current?.closest('[data-testid="post-dialog-body"]') ?? null;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting) && state.current.hasNext) {
          loadMore();
        }
      },
      { root, rootMargin: "0px 0px 200px 0px" },
    );
    observer.observe(sentinel.current);
    return () => observer.disconnect();
  }, [loadMore]);

  useEffect(() => {
    emitStepEvent("dialog-ready");
  }, []);

  return (
    <LoggingSurface name="comments">
      <UIColumn xstyle={styles.list}>
        <CommentOrderSelector feedback={data} onChange={changeOrder} />
        {edges.map((edge) => (
          <Comment key={edge.node.id} comment={edge.node} />
        ))}
        {hasNext && !isLoadingNext ? (
          <UIPressable label="View more comments" onPress={loadMore} showOverlay={false} xstyle={styles.more} testid="dialog-more-comments">
            <UIText type="meta" color="secondary" weight="semibold">
              {fbt("View more comments", "loads more comments in the post dialog")}
            </UIText>
          </UIPressable>
        ) : null}
        {isLoadingNext || isRefetching ? (
          <UIRow xstyle={styles.loading}>
            <UISpinner size={20} />
          </UIRow>
        ) : null}
        <div ref={sentinel} data-testid="comments-sentinel" {...stylex.props(styles.sentinel)} />
      </UIColumn>
    </LoggingSurface>
  );
}
